using Gravicode.Science.GraviNum;
using Gravicode.Science.SciNet.IO;
using Xunit;

namespace Gravicode.Science.Tests.SciNet;

/// <summary>
/// The managed HDF5 reader against files written by h5py 3.16.0 / HDF5 2.0.0 (see
/// Fixtures/gen_hdf5.py). Expected values are what h5py reads back from the same files; the larger
/// arrays are generated by a formula in the script, repeated here.
/// </summary>
public class Hdf5Tests
{
    private static Hdf5File Open(string name) => Hdf5File.Open(IOAssert.Fixture(name));

    private static double[] Big() // layout/chunked: ((i*23 + j) % 17) - 8 over 37 x 23
    {
        var r = new double[37 * 23];
        for (var k = 0; k < r.Length; k++) r[k] = k % 17 - 8;
        return r;
    }

    [Theory]
    [InlineData("h5_v0.h5", 0)]
    [InlineData("h5_v2.h5", 2)]
    [InlineData("h5_latest.h5", 3)]
    [InlineData("h5_off4.h5", 2)] // h5py needs superblock 2 for 4-byte offsets
    public void SuperblockVersions(string file, int version)
    {
        using var f = Open(file);
        Assert.Equal(version, f.SuperblockVersion);
        Assert.Equal(0, f.UserBlockSize);
        Assert.True(Hdf5File.IsHdf5(IOAssert.Fixture(file)));
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")]
    public void EveryNumericTypeAndByteOrder(string file)
    {
        using var f = Open(file);
        var g = f.Root.Group("num");
        Assert.Equal(new sbyte[] { -128, -1, 0, 1, 127 }, (sbyte[])g.Dataset("i1").ReadArray());
        Assert.Equal(new byte[] { 0, 1, 200, 255 }, (byte[])g.Dataset("u1").ReadArray());
        Assert.Equal(new short[] { -32768, -2, 3, 32767 }, (short[])g.Dataset("i2").ReadArray());
        Assert.Equal(new ushort[] { 0, 1, 65535, 4660 }, (ushort[])g.Dataset("u2be").ReadArray());
        Assert.True(g.Dataset("u2be").DataType.IsBigEndian);
        Assert.Equal(new[] { int.MinValue, 5, 7, int.MaxValue }, (int[])g.Dataset("i4be").ReadArray());
        Assert.Equal(new[] { 2, 2 }, g.Dataset("i4be").Shape);
        Assert.Equal(new uint[] { 0, 4294967295, 12345 }, (uint[])g.Dataset("u4").ReadArray());
        Assert.Equal(new[] { -(1L << 62), -1, 1L << 53, 9 }, (long[])g.Dataset("i8").ReadArray());
        Assert.Equal(new[] { 0UL, 1UL << 63, (1UL << 40) + 1 }, (ulong[])g.Dataset("u8be").ReadArray());
        // h5py: [0.5, -1.25, 65504.0, 0.0010004] (float16 rounds 1e-3)
        var half = (Half[])g.Dataset("f2").ReadArray();
        Assert.Equal(new[] { 0.5, -1.25, 65504.0 }, half[..3].Select(h => (double)h));
        IOAssert.Close(0.0010004043579101562, (double)half[3], 0, "f2[3]");
        Assert.Equal(new[] { 1.5f, -2.25f, 3.0f, 4.0e10f, -5.5e-10f, 0f }, (float[])g.Dataset("f4be").ReadArray());
        Assert.Equal(new[] { Math.PI, -Math.E, 1e-300, 1e300 }, (double[])g.Dataset("f8be").ReadArray());
        var f8 = g.Dataset("f8").Read();
        Assert.Equal(new[] { 2, 3, 4 }, f8.Shape.ToArray());
        Assert.Equal(Enumerable.Range(0, 24).Select(i => i * 0.5 - 3).ToArray(), f8.ToArray());
        Assert.Equal(new[] { true, false, true, true }, (bool[])g.Dataset("bool").ReadArray());
        Assert.True(g.Dataset("bool").DataType.IsBoolean);
        Assert.Equal(new[] { 1.0, 0, 1, 1 }, g.Dataset("bool").Read().ToArray());
        var sc = g.Dataset("scalar");
        Assert.True(sc.IsScalar);
        Assert.Equal(2.5, sc.Read().ToArray().Single());
        var empty = g.Dataset("empty");
        Assert.Equal(new[] { 0, 3 }, empty.Shape);
        Assert.Equal(0, empty.Read().Size);
        // Conversions: exact where the value fits, refused where it does not.
        Assert.Equal(new[] { -128.0, -1, 0, 1, 127 }, g.Dataset("i1").Read<double>());
        Assert.Equal(new long[] { 0, 4294967295, 12345 }, g.Dataset("u4").Read<long>());
        Assert.Throws<OverflowException>(() => g.Dataset("u4").Read<short>());
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")]
    public void Strings(string file)
    {
        using var f = Open(file);
        var s = f.Root.Group("str");
        IOAssert.Strings(["alpha", "be", "gamma12345"], s.Dataset("fixed").ReadStrings());
        IOAssert.Strings(["héllo", "", "日本語"], s.Dataset("vlen_utf8").ReadStrings());
        Assert.True(s.Dataset("vlen_utf8").DataType.IsVariableLengthString);
        IOAssert.Strings(["abc", "de"], s.Dataset("vlen_ascii").ReadStrings());
        var sv = s.Dataset("scalar_vlen");
        Assert.True(sv.IsScalar);
        IOAssert.Strings(["scalar text"], sv.ReadStrings());
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")]
    public void CompoundEnumVlenAndReferences(string file)
    {
        using var f = Open(file);
        var c = f.Root.Group("cmp");
        var rec = c.Dataset("rec");
        Assert.Equal(["x", "n", "tag", "v"], rec.DataType.Members.Select(m => m.Name));
        var cols = rec.ReadCompound();
        Assert.Equal(new[] { 1.5, -2.0 }, (double[])cols["x"]);
        Assert.Equal(new[] { -7, 9 }, (int[])cols["n"]); // big-endian member inside a little-endian record
        IOAssert.Strings(["ab", "xyz"], (string[])cols["tag"]);
        var v = (Array[])cols["v"];
        Assert.Equal(new[] { 1.0f, 2.0f }, (float[])v[0]);
        Assert.Equal(new[] { 3.0f, -4.0f }, (float[])v[1]);
        var rows = (Dictionary<string, object?>[])rec.ReadArray();
        Assert.Equal(-2.0, rows[1]["x"]);
        Assert.Equal("ab", rows[0]["tag"]);

        var en = c.Dataset("enum");
        Assert.Equal(Hdf5TypeClass.Enum, en.DataType.Class);
        Assert.Contains(new KeyValuePair<string, long>("BLUE", 42), en.DataType.EnumMembers);
        Assert.Equal(new short[] { 0, 42, 1, 42 }, (short[])en.ReadArray());

        var vl = (Array[])c.Dataset("vlen").ReadArray();
        Assert.Equal(new[] { 1, 2, 3 }, (int[])vl[0]);
        Assert.Empty((int[])vl[1]);
        Assert.Equal(new[] { -5 }, (int[])vl[2]);

        var refs = c.Dataset("refs").ReadReferences();
        Assert.Equal(3, refs.Length);
        var target = Assert.IsType<Hdf5Dataset>(f.Dereference(refs[0]));
        Assert.Equal(new[] { 2, 3, 4 }, target.Shape);
        Assert.Equal(f.Root.Dataset("num/f8").Address, target.Address);
        Assert.Equal(new short[] { 1, 2, 3, 4, 5, 6 }, (short[])((Hdf5Dataset)f.Dereference(refs[1])).ReadArray());
        Assert.IsType<Hdf5Group>(f.Dereference(refs[2]));
        var ra = (Hdf5Reference)c.GetAttribute("ref_attr")!;
        Assert.Equal(f.Root.Dataset("num/i1").Address, ra.Address);
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")]
    public void LayoutsAndFilters(string file)
    {
        using var f = Open(file);
        var l = f.Root.Group("layout");
        var compact = l.Dataset("compact");
        Assert.Equal(Hdf5Layout.Compact, compact.Layout);
        Assert.Equal(new[] { 0, 11, 22, 33, 44, 55 }, (int[])compact.ReadArray());
        var contig = l.Dataset("contig");
        Assert.Equal(Hdf5Layout.Contiguous, contig.Layout);
        Assert.Equal(Enumerable.Range(0, 30).Select(i => (double)i).ToArray(), contig.Read().ToArray());

        var big = Big();
        var ch = l.Dataset("chunked");
        Assert.Equal(Hdf5Layout.Chunked, ch.Layout);
        Assert.Equal(new[] { 8, 5 }, ch.ChunkShape);
        Assert.Equal(big, ch.Read().ToArray());

        var ds = l.Dataset("deflate_shuffle");
        Assert.Equal(new[] { 2, 1 }, ds.Filters.Select(x => x.Id));
        Assert.Equal(big.Select(x => x / 4).ToArray(), ds.Read().ToArray());

        var fl = l.Dataset("fletcher");
        Assert.Contains(fl.Filters, x => x.Id == 3);
        var expect = new double[37 * 4];
        for (var i = 0; i < 37; i++) for (var j = 0; j < 4; j++) expect[i * 4 + j] = big[i * 23 + j];
        Assert.Equal(expect, fl.Read().ToArray());

        // Unwritten chunks read as the fill value.
        var m = l.Dataset("missing_chunks").Read().ToArray();
        for (var i = 0; i < 20; i++)
            for (var j = 0; j < 20; j++)
            {
                var want = i < 5 && j < 5 ? 1.0 : (i, j) == (12, 17) ? 7.0 : -1.5;
                Assert.True(m[i * 20 + j] == want, $"missing_chunks[{i},{j}] = {m[i * 20 + j]}, expected {want}");
            }

        var rs = l.Dataset("resizable");
        Assert.Equal(new long[] { -1 }, rs.MaxShape);
        Assert.Equal(Enumerable.Range(0, 10).Select(i => (long)i).ToArray(), (long[])rs.ReadArray());
        Assert.Equal(Enumerable.Range(0, 35).Select(i => (double)i).ToArray(), l.Dataset("two_unlimited").Read().ToArray());

        var ex = Assert.Throws<NotSupportedException>(() => l.Dataset("lzf").Read());
        Assert.Contains("lzf", ex.Message);
    }

    [Theory]
    [InlineData("h5_v0.h5", "chunked")]
    [InlineData("h5_latest.h5", "deflate_shuffle")]
    [InlineData("h5_latest.h5", "contig")]
    public void SlicesReadOnlyTheirRegion(string file, string name)
    {
        using var f = Open(file);
        var d = f.Root.Group("layout").Dataset(name);
        var full = d.Read();
        var cols = full.Shape[1];
        int[] start = [1, 2], count = [3, 4];
        var s = d.ReadSlice(start, count);
        Assert.Equal(count, s.Shape.ToArray());
        var fs = full.ToArray();
        var ss = s.ToArray();
        for (var i = 0; i < 3; i++)
            for (var j = 0; j < 4; j++)
                Assert.Equal(fs[(i + 1) * cols + j + 2], ss[i * 4 + j]);
        Assert.Throws<ArgumentOutOfRangeException>(() => d.ReadSlice([0, 0], [100, 1]));
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")]
    public void LinksAndNavigation(string file)
    {
        using var f = Open(file);
        Assert.Equal(["attrs", "cmp", "layout", "links", "many", "num", "str"], f.Root.Keys.Where(k => k is not ("index" or "ordered" or "committed" or "ctype")));
        var soft = f.Root.Dataset("links/soft");
        Assert.Equal(new sbyte[] { -128, -1, 0, 1, 127 }, (sbyte[])soft.ReadArray());
        Assert.Equal(f.Root.Dataset("num/u1").Address, f.Root.Dataset("links/hard").Address);
        Assert.Equal(42.0, ((Hdf5Dataset)f["/links/deep/er/leaf"]).Read().ToArray().Single());
        Assert.Equal("/links/deep/er/leaf", f["links/deep/er/leaf"].Path);
        Assert.Equal(42.0, f.Root.Group("links/deep").Dataset("er/leaf").Read().ToArray().Single());
        Assert.False(f.Root.Contains("links/nope"));
        Assert.Throws<KeyNotFoundException>(() => f["missing"]);
        var many = f.Root.Group("many");
        Assert.Equal(Enumerable.Range(0, 12).Select(i => $"g{i:00}"), many.Keys);
        Assert.Equal(12, many.Groups.Count);
        var visited = new List<string>();
        f.Root.Group("links").Visit(o => visited.Add(o.Name));
        Assert.Contains("leaf", visited);
    }

    [Theory]
    [InlineData("h5_v0.h5")]
    [InlineData("h5_latest.h5")] // 27 attributes: dense storage (fractal heap + v2 B-tree)
    public void Attributes(string file)
    {
        using var f = Open(file);
        var a = f.Root.Group("attrs").Attributes;
        Assert.Equal(file == "h5_latest.h5" ? 27 : 26, a.Count);
        for (var i = 0; i < 20; i++) Assert.Equal(i * 1.5, (double)a[$"a{i:00}"].Value!);
        Assert.Equal("attribute text", a["text"].Value);
        Assert.Equal("fixed", a["fixed"].AsString());
        Assert.Equal(new long[] { 1, 2, 3 }, (long[])a["ints"].Value!);
        Assert.Equal(new[] { 1.0, 2, 3 }, a["ints"].ToDoubles());
        IOAssert.Strings(["x", "yy"], (string[])a["strs"].Value!);
        Assert.True(a["empty"].IsNull);
        Assert.Null(a["empty"].Value);
        Assert.Equal(true, a["flag"].Value);
        Assert.Equal(a.Keys.OrderBy(k => k, StringComparer.Ordinal), a.Keys); // name order, as h5py lists them
    }

    [Fact]
    public void LatestFormatChunkIndexes()
    {
        using var f = Open("h5_latest.h5");
        var x = f.Root.Group("index");
        Assert.Equal(Enumerable.Range(0, 12).Select(i => (double)i), x.Dataset("single").Read().ToArray());
        Assert.Equal(Enumerable.Range(0, 6).ToArray(), (int[])x.Dataset("single_raw").ReadArray());
        Assert.Equal(Enumerable.Range(0, 10).Select(i => i * 3).ToArray(), (int[])x.Dataset("implicit").ReadArray());
        Assert.Equal(Enumerable.Range(0, 50).Select(i => (double)i), x.Dataset("fixed").Read().ToArray());
        Assert.Equal(Enumerable.Range(0, 2000).Select(i => (byte)(i % 251)).ToArray(), (byte[])x.Dataset("fixed_paged").ReadArray());
        Assert.Equal(Enumerable.Range(0, 700).Select(i => i * 2 - 7).ToArray(), (int[])x.Dataset("ext").ReadArray());
        var e2 = x.Dataset("ext2d");
        Assert.Equal(new long[] { 4, -1 }, e2.MaxShape);
        Assert.Equal(Enumerable.Range(0, 200).Select(i => i / 8.0), e2.Read().ToArray());
        Assert.Equal(Enumerable.Range(0, 45).Select(i => i * 1000L).ToArray(), (long[])x.Dataset("bt2").ReadArray());
        Assert.Equal(Enumerable.Range(0, 35).ToArray(), (int[])x.Dataset("edge_unfiltered").ReadArray());
        var slice = x.Dataset("ext2d").ReadSlice([1, 40], [2, 10]).ToArray();
        for (var i = 0; i < 2; i++)
            for (var j = 0; j < 10; j++)
                Assert.Equal(((i + 1) * 50 + j + 40) / 8.0, slice[i * 10 + j]);
    }

    [Fact]
    public void HugeDenseAttributeAndCommittedDatatype()
    {
        using var f = Open("h5_latest.h5");
        // An 8200-double attribute exceeds the fractal heap's 64 KiB managed limit, so its heap ID
        // is a key into the heap's huge-object B-tree.
        var huge = f.Root.Group("attrs").Attributes["huge"].ToDoubles();
        Assert.Equal(Enumerable.Range(0, 8200).Select(i => (double)i), huge);

        var t = Assert.IsType<Hdf5NamedType>(f["ctype"]);
        Assert.Equal(Hdf5TypeClass.Compound, t.DataType.Class);
        Assert.DoesNotContain("ctype", f.Root.Datasets.Keys);
        var d = f.Root.Dataset("committed"); // its datatype message is shared with /ctype
        var cols = d.ReadCompound();
        Assert.Equal(new[] { 1.5, 3.5, 5.5 }, (double[])cols["a"]);
        Assert.Equal(new short[] { 2, 4, 6 }, (short[])cols["b"]);
        var rec = ((Dictionary<string, object?>[])d.Attributes["shared_attr"].Value!)[0];
        Assert.Equal(9.0, rec["a"]);
        Assert.Equal((short)8, rec["b"]);
    }

    [Fact]
    public void CreationOrderIsKeptWhenTracked()
    {
        using var f = Open("h5_latest.h5");
        var g = f.Root.Group("ordered");
        Assert.Equal(["zeta", "alpha", "mid"], g.Keys);
        Assert.Equal(["z", "a"], g.Attributes.Keys);
    }

    [Fact]
    public void SuperblockV2WithDenseAttributes()
    {
        using var f = Open("h5_v2.h5");
        var d = f.Root.Dataset("data");
        Assert.Equal(Enumerable.Range(0, 12).Select(i => (double)i), d.Read().ToArray());
        Assert.Equal(12, d.Attributes.Count);
        Assert.Equal(11L, Convert.ToInt64(d.GetAttribute("k11")));
        Assert.Equal(Enumerable.Range(0, 100).ToArray(), f.Root.Dataset("chunked").Read<int>());
    }

    [Fact]
    public void FourByteOffsets()
    {
        using var f = Open("h5_off4.h5");
        Assert.Equal(new[] { 1.0, 2, 3 }, f.Root.Dataset("v").Read().ToArray());
        Assert.Equal(Enumerable.Range(0, 40).Select(i => (short)i).ToArray(), (short[])f.Root.Dataset("c").ReadArray());
        IOAssert.Strings(["four"], f.Root.Dataset("g/s").ReadStrings());
        Assert.Equal(-3, f.Root.Group("g").GetAttribute("n"));
    }

    [Fact]
    public void MatlabWrittenFileWithUserBlock()
    {
        // A real MATLAB 7.4 v7.3 file from SciPy's test data: superblock 0 after a 512-byte user block.
        using var f = Open("scipy/testhdf5_7.4_GLNX86.mat");
        Assert.Equal(512, f.UserBlockSize);
        var d = f.Root.Dataset("testdouble");
        Assert.Equal(new[] { 9, 1 }, d.Shape);
        Assert.Equal("double", d.Attributes["MATLAB_class"].AsString());
        var v = d.Read().ToArray();
        for (var i = 0; i < 9; i++) IOAssert.Close(i * Math.PI / 4, v[i], 1e-15, $"testdouble[{i}]");
    }

    [Fact]
    public void StreamsAndRejection()
    {
        var bytes = File.ReadAllBytes(IOAssert.Fixture("h5_latest.h5"));
        using (var f = Hdf5File.Open(new MemoryStream(bytes)))
            Assert.Equal(Enumerable.Range(0, 700).Select(i => i * 2 - 7).ToArray(), (int[])f.Root.Dataset("index/ext").ReadArray());
        using (var f = Hdf5File.Open(new BufferedStream(new MemoryStream(bytes))))
            Assert.Equal(Big().Select(x => x / 4).ToArray(), f.Root.Dataset("layout/deflate_shuffle").Read().ToArray());
        Assert.Throws<InvalidDataException>(() => Hdf5File.Open(new MemoryStream(new byte[2048])));
        Assert.False(Hdf5File.IsHdf5(new MemoryStream(new byte[100])));
    }
}
